{

"kind": "propose",
"summary": "Liveness probe is too strict, killing pods during startup. Increase initialDelaySeconds to allow app to start.",
"hypotheses": [
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "Pods are killed during startup due to liveness probe failing before the app is ready.",
        "supporting": ["killed_during_startup", "probe_kills", "ev-rollout_history", "ev-pod_states"],
        "contradicting": ["crashed_on_its_own", "probe_timeouts"],
        "missing": ["container_logs_tail"],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "No logs to confirm app behavior during startup, but probe timing seems mismatched.",
        "supporting": ["ev-target_events", "ev-rollout_history"],
        "contradicting": [],
        "missing": ["container_logs_tail"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "finance",
        "name": "ledger",
        "uid": "uid-deployment-ledger"
    },
    "params": {
        "container": "app",
        "liveness": {
            "initialDelaySeconds": 30,
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Allow the app more time to start before liveness probe checks, reducing premature restarts.",
    "rationale": "Pods are killed during startup (killed_during_startup=true) with liveness probe failures. The current liveness probe has initialDelaySeconds=10 and timeoutSeconds=1, which is too short for an app that takes 32s to start. Increasing initialDelaySeconds to 30 and timeoutSeconds to 5 aligns with the observed startup time and prevents premature kills.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "killed_during_startup", "probe_kills", "crashed_on_its_own", "probe_timeouts"],
    "cited_predicates": ["killed_during_startup", "probe_kills", "crashed_on_its_own", "probe_timeouts"]
}
}

